// ──────────────────────────── tests ──────────────────────────────────────

Test("an uncancelled run completes everything", async () =>
{
    var done = new List<string>();
    var result = await ProcessAll(["a", "b", "c"], done, CancellationToken.None);

    Eq(result, new[] { "a", "b", "c" });
    Eq(done, new[] { "a", "b", "c" });
});

Test("cancelling before the start throws immediately", async () =>
{
    using var cts = new CancellationTokenSource();
    cts.Cancel();

    var done = new List<string>();
    await ThrowsAsync<OperationCanceledException>(
        () => ProcessAll(["a", "b"], done, cts.Token));

    Eq(done, new List<string>());   // nothing ran
});

Test("cancelling partway stops the remaining work", async () =>
{
    using var cts = new CancellationTokenSource();
    var done = new List<string>();

    var running = ProcessAll(["a", "b", "c", "d"], done, cts.Token);
    await Sleep(45);      // let a couple through
    await cts.CancelAsync();

    await ThrowsAsync<OperationCanceledException>(() => running);
    Ok(done.Count is > 0 and < 4, $"expected a partial run, got {done.Count}");
});

Test("ProcessWhatYouCan returns partial results instead of throwing", async () =>
{
    using var cts = new CancellationTokenSource();
    var done = new List<string>();

    var running = ProcessWhatYouCan(["a", "b", "c", "d"], done, cts.Token);
    await Sleep(45);
    await cts.CancelAsync();

    var result = await running;                    // no exception
    Ok(result.Count is > 0 and < 4, $"expected partial, got {result.Count}");
    Eq(result, done);
});

Test("ProcessWhatYouCan with no cancellation does all of it", async () =>
{
    var done = new List<string>();
    Eq(await ProcessWhatYouCan(["a", "b"], done, CancellationToken.None),
       new[] { "a", "b" });
});

Test("work that finishes inside the timeout returns normally", async () =>
{
    var result = await WithTimeout(
        async ct => { await Task.Delay(10, ct); return "done"; },
        timeoutMs: 500, CancellationToken.None);

    Eq(result, "done");
});

Test("work that overruns the timeout is cancelled", async () =>
{
    await ThrowsAsync<OperationCanceledException>(() => WithTimeout(
        async ct => { await Task.Delay(5000, ct); return "done"; },
        timeoutMs: 40, CancellationToken.None));
});

Test("the caller's token cancels it too, before the timeout", async () =>
{
    using var cts = new CancellationTokenSource();
    var running = WithTimeout(
        async ct => { await Task.Delay(5000, ct); return "done"; },
        timeoutMs: 10_000, cts.Token);

    await Sleep(30);
    await cts.CancelAsync();

    await ThrowsAsync<OperationCanceledException>(() => running);
});

Test("the work is actually told to stop — its own token fires", async () =>
{
    var innerSawCancellation = false;

    await ThrowsAsync<OperationCanceledException>(() => WithTimeout(
        async ct =>
        {
            try { await Task.Delay(5000, ct); }
            catch (OperationCanceledException) { innerSawCancellation = true; throw; }
            return "done";
        },
        timeoutMs: 40, CancellationToken.None));

    Ok(innerSawCancellation, "the timeout must reach the work, not just abandon it");
});

// ──────────────────────────── tests ──────────────────────────────────────

Test("all succeeding means no throw", async () =>
    await RunAllCollectingErrors(
        () => Task.CompletedTask,
        () => Task.CompletedTask));

Test("one failure is reported", async () =>
{
    var error = await ThrowsAsync<AggregateException>(() => RunAllCollectingErrors(
        () => Task.CompletedTask,
        () => throw new InvalidOperationException("boom")));

    Eq(error.InnerExceptions.Count, 1);
    Eq(error.InnerExceptions[0].Message, "boom");
});

Test("EVERY failure is reported, not just the first", async () =>
{
    // await on WhenAll rethrows only the first — this must not.
    var error = await ThrowsAsync<AggregateException>(() => RunAllCollectingErrors(
        () => throw new InvalidOperationException("first"),
        () => Task.CompletedTask,
        () => throw new InvalidOperationException("second")));

    Eq(error.InnerExceptions.Count, 2);
    Eq(error.InnerExceptions.Select(e => e.Message).OrderBy(m => m),
       new[] { "first", "second" });
});

Test("failing work does not stop the others from running", async () =>
{
    var ran = new List<string>();

    await ThrowsAsync<AggregateException>(() => RunAllCollectingErrors(
        () => throw new InvalidOperationException("boom"),
        async () => { await Task.Delay(10); lock (ran) ran.Add("b"); },
        async () => { await Task.Delay(10); lock (ran) ran.Add("c"); }));

    Eq(ran.Count, 2);
});

Test("settled separates successes from failures", async () =>
{
    var (ok, errors) = await RunAllSettled(
        () => Task.FromResult("a"),
        () => throw new InvalidOperationException("bad"),
        () => Task.FromResult("c"));

    Eq(ok, new[] { "a", "c" });
    Eq(errors, new[] { "bad" });
});

Test("settled never throws, even when everything fails", async () =>
{
    var (ok, errors) = await RunAllSettled(
        () => throw new InvalidOperationException("x"),
        () => throw new InvalidOperationException("y"));

    Eq(ok, new List<string>());
    Eq(errors.OrderBy(e => e), new[] { "x", "y" });
});

Test("settled with no work is empty, not a crash", async () =>
{
    var (ok, errors) = await RunAllSettled();
    Eq(ok, new List<string>());
    Eq(errors, new List<string>());
});

Test("fire-and-forget returns before the work finishes", () =>
{
    var finished = false;
    FireAndForget(async () => { await Task.Delay(80); finished = true; }, _ => { });

    Eq(finished, false);   // we did not wait
});

Test("a fire-and-forget failure reaches onError instead of vanishing", async () =>
{
    Exception? seen = null;
    FireAndForget(() => throw new InvalidOperationException("background boom"),
                  e => seen = e);

    await Sleep(60);
    NotNull(seen);
    Eq(seen!.Message, "background boom");
});

Test("a synchronous throw inside the work is caught too", async () =>
{
    // Not every failure happens after an await.
    Exception? seen = null;
    FireAndForget(() => throw new ArgumentException("immediate"), e => seen = e);

    await Sleep(60);
    Eq(seen?.Message, "immediate");
});

Test("an un-awaited Task hides its exception until you await it", async () =>
{
    // The root cause behind every pitfall in this file: the exception is
    // STORED ON THE TASK. Nothing surfaces it until someone awaits.
    var task = Failing();
    await Sleep(20);

    Ok(task.IsFaulted, "the task failed, silently");
    await ThrowsAsync<InvalidOperationException>(() => task);

    static async Task Failing()
    {
        await Task.Yield();
        throw new InvalidOperationException("stored on the task");
    }
});

// NOTE on `async void`: it has no Task at all, so there is nowhere to store
// the exception — it is raised on the thread pool and TAKES THE PROCESS
// DOWN. That is not demonstrated here for the obvious reason that it would
// kill this test run. Use `async Task` everywhere except an event handler.

// ──────────────────────────── tests ──────────────────────────────────────

Test("it streams every item across every page", async () =>
{
    var api = new PagedApi(pages: 3, perPage: 2);
    Eq(await ReadEverything(api), new[] { "1", "2", "3", "4", "5", "6" });
});

Test("it stops at the empty page", async () =>
{
    var api = new PagedApi(pages: 2, perPage: 2);
    Eq(await ReadEverything(api), new[] { "1", "2", "3", "4" });

    // 2 pages of data + 1 empty page to learn it is over.
    Eq(api.PagesFetched, 3);
});

Test("an empty source yields nothing", async () =>
{
    var api = new PagedApi(pages: 0, perPage: 2);
    Eq(await ReadEverything(api), new List<string>());
});

Test("items arrive one at a time, before the source is exhausted", async () =>
{
    var api = new PagedApi(pages: 5, perPage: 2);
    var seen = new List<string>();

    await foreach (var item in ReadAll(api))
    {
        seen.Add(item);
        if (seen.Count == 1)
            // The whole point: usable output before everything is fetched.
            Ok(api.PagesFetched < 5, $"buffered all {api.PagesFetched} pages first");
    }

    Eq(seen.Count, 10);
});

Test("taking 3 does not fetch every page", async () =>
{
    var api = new PagedApi(pages: 10, perPage: 2);
    Eq(await FirstN(api, 3), new[] { "1", "2", "3" });

    // 2 pages covers 4 items — enough for 3. Not 10.
    Ok(api.PagesFetched <= 2, $"fetched {api.PagesFetched} pages for 3 items");
});

Test("asking for more than exists returns what there is", async () =>
{
    var api = new PagedApi(pages: 2, perPage: 2);
    Eq(await FirstN(api, 99), new[] { "1", "2", "3", "4" });
});

Test("asking for zero fetches nothing", async () =>
{
    var api = new PagedApi(pages: 10, perPage: 2);
    Eq(await FirstN(api, 0), new List<string>());
});

Test("cancellation stops the stream", async () =>
{
    var api = new PagedApi(pages: 50, perPage: 2);
    using var cts = new CancellationTokenSource();
    var seen = 0;

    await ThrowsAsync<OperationCanceledException>(async () =>
    {
        await foreach (var _ in ReadAll(api).WithCancellation(cts.Token))
        {
            if (++seen == 3) await cts.CancelAsync();
        }
    });

    Ok(api.PagesFetched < 50, $"should have stopped early, fetched {api.PagesFetched}");
});

